# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NOKTA GRAFİĞİ VE ÇİZGİ GRAFİĞİ ANALİZİ (MAT.7.6.1)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Nokta Grafiği (Sürekli / Kesikli Dağılım)</text>\n  <line x1="55" y1="195" x2="310" y2="195" stroke="#1e293b" stroke-width="2"/>\n  <text x="80" y="214" text-anchor="middle" font-size="11" fill="#334155">10</text>\n  <text x="130" y="214" text-anchor="middle" font-size="11" fill="#334155">12</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" fill="#334155">14</text>\n  <text x="230" y="214" text-anchor="middle" font-size="11" fill="#334155">16</text>\n  <text x="280" y="214" text-anchor="middle" font-size="11" fill="#334155">18</text>\n  <circle cx="80" cy="180" r="5" fill="#2563eb"/>\n  <circle cx="130" cy="180" r="5" fill="#2563eb"/>\n  <circle cx="130" cy="165" r="5" fill="#2563eb"/>\n  <circle cx="180" cy="180" r="5" fill="#1d4ed8"/>\n  <circle cx="180" cy="165" r="5" fill="#1d4ed8"/>\n  <circle cx="180" cy="150" r="5" fill="#1d4ed8"/>\n  <circle cx="180" cy="135" r="5" fill="#1d4ed8"/>\n  <circle cx="230" cy="180" r="5" fill="#2563eb"/>\n  <circle cx="230" cy="165" r="5" fill="#2563eb"/>\n  <circle cx="280" cy="180" r="5" fill="#2563eb"/>\n  <text x="182" y="105" text-anchor="middle" font-size="11" fill="#1e40af">Simetrik Dağılım: Ortalama = Ortanca = Tepe Değer (14)</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Çizgi Grafiği (Zamana Bağlı Değişim)</text>\n  <line x1="395" y1="195" x2="650" y2="195" stroke="#1e293b" stroke-width="2"/>\n  <line x1="395" y1="90" x2="395" y2="195" stroke="#1e293b" stroke-width="2"/>\n  <polyline points="420,175 470,150 520,160 570,120 620,100" fill="none" stroke="#16a34a" stroke-width="3"/>\n  <circle cx="420" cy="175" r="4" fill="#15803d"/>\n  <circle cx="470" cy="150" r="4" fill="#15803d"/>\n  <circle cx="520" cy="160" r="4" fill="#15803d"/>\n  <circle cx="570" cy="120" r="4" fill="#15803d"/>\n  <circle cx="620" cy="100" r="4" fill="#15803d"/>\n  <text x="420" y="214" text-anchor="middle" font-size="10" fill="#334155">Pzt</text>\n  <text x="470" y="214" text-anchor="middle" font-size="10" fill="#334155">Sal</text>\n  <text x="520" y="214" text-anchor="middle" font-size="10" fill="#334155">Çar</text>\n  <text x="570" y="214" text-anchor="middle" font-size="10" fill="#334155">Per</text>\n  <text x="620" y="214" text-anchor="middle" font-size="10" fill="#334155">Cum</text>\n  <text x="517" y="230" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Artış ve Azalış Eğilimini En İyi Gösterir</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DAİRE GRAFİĞİ MERKEZ AÇI DÖNÜŞÜMÜ VE GRAFİK SEÇİMİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Daire Grafiği (Bütünün Parça Oranları)</text>\n  <circle cx="110" cy="145" r="58" fill="#fde047" stroke="#ca8a04" stroke-width="2"/>\n  <path d="M 110 145 L 110 87 A 58 58 0 0 1 168 145 Z" fill="#3b82f6"/>\n  <path d="M 110 145 L 168 145 A 58 58 0 0 1 110 203 Z" fill="#22c55e"/>\n  <text x="135" y="125" font-size="10" font-weight="bold" fill="#ffffff">90° (%25)</text>\n  <text x="132" y="170" font-size="10" font-weight="bold" fill="#ffffff">90° (%25)</text>\n  <text x="62" y="150" font-size="10" font-weight="bold" fill="#854d0e">180° (%50)</text>\n  <text x="185" y="105" font-size="11" fill="#334155">• Tam daire = 360° (%100)</text>\n  <text x="185" y="130" font-size="11" fill="#334155">• Yarım daire = 180° (%50)</text>\n  <text x="185" y="155" font-size="11" fill="#334155">• Çeyrek daire = 90° (%25)</text>\n  <text x="185" y="180" font-size="11" fill="#334155">• Beşte bir = 72° (%20)</text>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Merkez Açı = (Kategori / Toplam) × 360°</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Hangi Grafik Ne Zaman Seçilir?</text>\n  <text x="375" y="100" font-size="11" fill="#334155">• Sütun Grafiği: Kategorilerin frekansını karşılaştırma</text>\n  <text x="375" y="124" font-size="11" fill="#334155">• Daire Grafiği: Parçanın bütüne oranını gösterme</text>\n  <text x="375" y="148" font-size="11" fill="#334155">• Çizgi Grafiği: Zaman içindeki değişimi izleme</text>\n  <text x="375" y="172" font-size="11" fill="#334155">• Nokta Grafiği: Küçük veri setinde yığılma ve uç değer</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Araştırma Amacı Grafik Seçimini Belirler</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MERKEZİ EĞİLİM VE YAYILIM ÖLÇÜLERİ İLE KARAR VERME</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Merkezi Eğilim Ölçüleri Seçimi</text>\n  <text x="40" y="100" font-size="11" fill="#334155">• Aritmetik Ortalama: Uç değer yoksa en iyi temsilci</text>\n  <text x="40" y="124" font-size="11" fill="#334155">• Ortanca (Medyan): Uç (aykırı) değer varsa seçilir</text>\n  <text x="40" y="148" font-size="11" fill="#334155">• Tepe Değer (Mod): En çok tercih edilen değeri bulur</text>\n  <text x="40" y="174" font-size="11" font-weight="bold" fill="#1e40af">Örnek: 10, 12, 13, 15, 100 (Uç değer = 100)</text>\n  <text x="40" y="196" font-size="11" fill="#334155">Ortalama = 30 (yanıltıcı) → Ortanca = 13 (uygun!)</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Yayılım (Tutarlılık / İstikrar) Ölçüleri</text>\n  <text x="375" y="100" font-size="11" fill="#334155">• Açıklık = En Büyük Değer - En Küçük Değer</text>\n  <text x="375" y="124" font-size="11" fill="#334155">• Ortalama Mutlak Sapma (OMS):</text>\n  <text x="375" y="144" font-size="10.5" fill="#334155">  Verilerin ortalamaya uzaklıklarının ortalamasıdır.</text>\n  <text x="375" y="172" font-size="11" font-weight="bold" fill="#166534">• Karar Kuralı:</text>\n  <text x="375" y="194" font-size="11" fill="#334155">  Açıklık ve OMS küçüldükçe istikrar (tutarlılık) artar!</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Düşük OMS = Daha Homojen ve Güvenilir Grup</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
